// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(42)); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        vm.deal(address(c), 1 ether);
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll(address(0x5678)) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}
